"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {readBankSettlementPreview} from '@/lib/cashier-bank-settlement';
import {CashierLedgerPeriodSelect} from './cashier-ledger-period-select';
import {CashierBankSettlementAction} from './cashier-bank-settlement-action';
export function CashierBankSettlementReview({scope,match,deposit,statement,amount}:{scope:HandoffScope;match:string;deposit:string;statement:string;amount:string}){
 const [posting,setPosting]=useState<{period:string;date:string}|null>(null),[preview,setPreview]=useState<ReturnType<typeof readBankSettlementPreview>|null>(null),[pending,setPending]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 const selection=posting?{scope,match,deposit,statement,amount,...posting}:null;
 async function prepare(){if(!selection||pending||lock.current)return;lock.current=true;setBusy(true);setError('');setPreview(null);try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh reconciliation.');const value=await hotelRpc('preview_bank_settlement',{p_tenant:scope.tenant,p_property:scope.property,p_match:match,p_period:selection.period,p_date:selection.date});const result=readBankSettlementPreview(value,selection);const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh reconciliation.');if(alive.current)setPreview(result);}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to prepare settlement.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <details><summary>Post matched credit to ledger</summary><p>Matched credit: {usd(Number(amount))}. The deposit transfer must be posted first.</p><CashierLedgerPeriodSelect scope={scope} disabled={busy||pending} onSelect={v=>{setPosting(v);setPreview(null)}}/><button type="button" disabled={!posting||busy||pending} onClick={()=>void prepare()}>Preview bank settlement</button>{error&&<p role="alert">{error}</p>}{preview&&<section aria-label="Settlement preview"><p>Debit bank and credit cash in transit: {usd(Number(amount))}</p><p>Posting date: {posting?.date}</p><p>Based on a manually recorded bank credit.</p><details><summary>Ledger references</summary><p>Bank account: {preview.debitAccount}</p><p>Transit account: {preview.creditAccount}</p></details></section>}<CashierBankSettlementAction scope={scope} match={match} selection={selection} preview={preview?.raw??null} onPending={setPending}/></details>
}
